const k=[{id:"identity-gollwitzer",title:"I01 · Gollwitzer ve Sheeran · 2006 · Duruma bağlı planlar ve hedefe ulaşma",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 kişinin katıldığı 94 bağımsız testte “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı: d = 0,65.",limitation:"83 deneysel ve 11 ilişkisel test farklı hedefleri ve yöntemleri kapsadı. Bu sonuç, belirli bir markanın alışkanlık paketini veya ODA’nın tam bu planını doğrulamaz."},{id:"identity-harkin",title:"I02 · Harkin ve arkadaşları · 2016 · Hedefe doğru ilerlemeyi izlemek",url:"https://doi.org/10.1037/bul0000025",type:"research",finding:"138 rastgele kontrollü çalışmada takip uygulamaları hedefe ulaşmayı ortalama olarak artırdı: d = 0,40. Yanlılığa göre düzeltilmiş tahmin daha küçüktü: d = 0,19.",limitation:"Hedefler ve kayıt yöntemleri farklıydı. Etkiyi değiştiren koşullara dair bulgular herkese açık paylaşım gerektirmez. Bu özet kayıt ve ertesi gün değerlendirmesi sınanmadı."},{id:"identity-cole",title:"I03 · Cole ve arkadaşları · 2021 · Zihinsel canlandırma ve davranış değişimi",url:"https://doi.org/10.3758/s13423-021-01880-6",type:"research",finding:"94 rastgele kontrollü çalışmada zihinsel canlandırmanın ortalama davranış etkisi g = 0,49’du. Canlandırma alt türlerinin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı.",limitation:"Örneklemlerin çoğu öğrenciydi. Bilgilerin raporlanma biçimi ve küçük alt gruplar kesinliği sınırlar. Üstün bir canlandırma türü veya kimlik meditasyonunun etkisi belirlenmedi."},{id:"identity-lally",title:"I04 · Lally ve arkadaşları · 2010 · Alışkanlıklar nasıl oluşur?",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"Verilere iyi uyan 39 modelde, otomatikleşmenin ulaşacağı sabit düzeyin %95’ine ulaşma süresi tahmininin ortancası 66 gündü. Tahminler 18-254 gün arasındaydı.",limitation:"96 gönüllü katıldı. Davranış 84 gün izlendi. Daha uzun süreler gözlemin ötesine uzanan tahminlerdi. Kimlik değişiminin son tarihi veya iki gün kaçırma kuralının testi değildi."},{id:"identity-habit-times",title:"I05 · Singh ve arkadaşları · 2024 · Alışkanlık oluşumu derlemesi",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"20 sağlık davranışı çalışmasının derlemesi, alışkanlık oluşumunda büyük farklılıklar buldu. Yalnızca dört çalışma oluşma sürelerini bildirdi.",limitation:"11 çalışmada yanlılık riski yüksekti. Öncesi ve sonrası alışkanlık puanı artışı, rastgele kontrollü bir neden-sonuç etkisi değildir. Herkese uyan bir oluşma süresi desteklenmiyor."},{id:"identity-wood-runger",title:"I06 · Wood ve Rünger · 2016 · Alışkanlık psikolojisi",url:"https://doi.org/10.1146/annurev-psych-122414-033417",type:"research",finding:"Derleme, tekrar eden ortamlarda yinelenen davranışlarla alışkanlıkların gelişmesini anlatır. Alışkanlıklar ve bilinçli süreçler birlikte işleyebilir.",limitation:"Birleştirilmiş etki vermeyen anlatı derlemesidir. Her ruh hâlini veya düşünceyi alışkanlık saymaz. Ortamı değiştirmenin her zaman çabadan üstün olduğunu kanıtlamaz."},{id:"identity-wood-everyday",title:"I07 · Wood, Quinn ve Kashy · 2002 · Günlük hayatta alışkanlıklar",url:"https://doi.org/10.1037/0022-3514.83.6.1281",type:"research",finding:"Öğrencilerin günlüklerini kullanan iki örneklemde, bildirilen davranışların %35’i ve %43’ü neredeyse her gün, aynı yerde yapılan alışkanlık tanımına uydu.",limitation:"Örneklemler 70 ve 209 öğrenci içeriyordu. Yüzdeler toplum tahmini veya zihnin dalma sıklığı değildir. Günlüklerle değerlendirme, kimlik değiştiren bir uygulamayı sınamadı."},{id:"identity-lieberman",title:"I10 · Lieberman ve arkadaşları · 2007 · Duyguları sözcüklere dökmek",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"Yüzlere bakan 30 yetişkinde, duygu sözcüğüyle adlandırma, cinsiyete uygun bir isimle adlandırmaya göre amigdalada daha düşük etkinlik yarattı.",limitation:"Küçük bir laboratuvar beyin görüntüleme çalışmasıdır. Gündelik duygusal toparlanmayı ölçmez. Kendi sıkıntını adlandırmanın onu azalttığını göstermez."},{id:"identity-breines",title:"I11 · Breines ve Chen · 2012 · Kendine şefkat ve gelişme isteği",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Dört kısa deney, şefkatli yanıtların ardından hemen ortaya çıkan gelişme isteğini destekledi. Bir deneyde ders çalışma süresi, hiçbir uygulama almayan koşula göre daha uzundu.",limitation:"Çoğunlukla öğrenci ve internet örneklemleri vardı. Etkiler karşılaştırmaya göre farklıydı. O çalışmada sınav notlarında istatistiksel olarak anlamlı fark bulunmadı. Kalıcı kimlik değişimi gösterilmedi."},{id:"identity-clear-identity",title:"I15 · James Clear · Kimliğe dayalı alışkanlıklar",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear, küçük davranışları istenen kimliğin kanıtı olarak sunar. Davranışı oy gibi anlatmak, uygulayıcının kullandığı bir benzetmedir.",limitation:"Yazarın yazısı deney değildir. Yayın yılı doğrulanmadı. Önce kimliği değiştirmenin üstünlüğü ve “asla iki kez kaçırma” kuralı doğrulanmış bilimsel yasalar değildir."},{id:"identity-task-belief",title:"I17 · Bandura · 1977 · Öz yeterlik kuramı",url:"https://doi.org/10.1037/0033-295X.84.2.191",type:"research",finding:"Çerçeve, belirli bir işi yapabileceğine dair beklentiyi anlatır. Kendi başardıkların, başkalarını gözlemek, cesaretlendirilmek ve bedenden gelen bilgiler bu beklentiyi besler.",limitation:"Kuramsal sentezdir. Birleştirilmiş uygulama etkisi tahmini değildir. Yapabileceğine dair inanç, insan olarak değerini ölçmez veya kimliğe oy verme yöntemini doğrulamaz."},{id:"identity-activity-identity",title:"I19 · Rhodes ve arkadaşları · 2025 · Fiziksel etkinliğe ilişkin kimlik uygulamaları",url:"https://doi.org/10.1080/17437199.2024.2412996",type:"research",finding:"4.939 yetişkini kapsayan 40 deneysel veya yarı deneysel etkide, fiziksel etkinliğe ilişkin kimlik ortalama olarak az değişti: g = 0,18.",limitation:"Davranış etkileri farklı bir 30 etkilik alt örneklemden geldi ve değişkenlik gösterdi. Derleme, kimliğin davranış değişimine neden olduğunu göstermez. Bütün kişiliğin dönüşümüne genellenemez."},{id:"identity-motor-rehearsal",title:"I18 · Toth ve arkadaşları · 2020 · Zihinsel prova ve görev performansı",url:"https://doi.org/10.1016/j.psychsport.2020.101672",type:"research",finding:"37 çalışmalık derleme, hareket becerileri veya görev performansında küçük, yanlılığa göre düzeltilmiş zihinsel prova etkisi bildirdi: r = 0,131.",limitation:"Açılan özet, toplam katılımcı sayısını veya güven aralığını doğrulamadı. Hareket becerisi kanıtları kimlik değişimini, iyileşmeyi veya duyguların biyolojisine ilişkin etkileri göstermez."}],t=[{schemaVersion:2,revision:2,id:"identity-1",courseId:"identity",locale:"tr",title:"Yine telefona mı daldın? Değiştirebileceğin anı bul",goal:"Tekrarlanan bir başlama anı seç. Bu hafta sana katkısı olacak başka bir davranış dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Aynı şey dikkatini dağıttı, öğleden sonran yine gitti mi? Değiştirebileceğin tek bir an bul.",reason:{id:"identity-1-reason",label:"Bu davranış şimdi neyi koruyor, sonraya neyi bırakıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["İşi yine geç saate kalmadan bitirmek","Yaratıcı çalışmama hayatımda yer açmak","Karşımdaki kişiye dikkatimi vermek"]},why:{id:"identity-1-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Önceliklerin değişse bile alışık olduğun bir ortam seni yine aynı davranışa götürebilir. Alışkanlık araştırmaları, tekrarlanan o davranışı bütün kişiliğinden ayrı tutar. “Öğle yemeğinden sonra işe başlamadan telefona dalıyorum” belirli bir durumu anlatır. “Ben tembelim” dediğinde ise üzerinde çalışabileceğin bir anı göremezsin. Hangi anda ne yaptığın belirsiz kalır.","Gündelik hayatında tanıyabileceğin tek bir an seç. O anda yapabileceğin yararlı bir alternatif belirle. Eski davranışın şimdi ne sağlıyor, sonraya ne bırakıyor, ona bak. Sonra alternatifini bir kez dene. Bu kurs boyunca aynı denemeyi geliştireceğiz. Kendini reddetmeden veya bambaşka biri olacağına söz vermeden küçük bir adımla başlayabilirsin."],example:{title:"Leyla raporun ilk cümlesini yazıyor",text:"Saat 13.30. Leyla masasına dönüyor. Raporu yazmaya başlamadan elini telefona uzatıyor. İşinin akşamları daha az uzamasını istiyor. Telefonu kenara koyup başlangıç için bir taslak cümle yazıyor. Cümle pek akıcı değil. Sonra yine telefona dalıyor. Kaydına, seçtiği anda ne yaptığını yazıyor. Bütün öğleden sonrayı hayatını değiştiren bir dönüşüm gibi anlatmıyor."}},move:{invitation:"Alışık olduğun tek bir an seç. İstediğin yola somut katkısı olacak başka bir davranış dene.",instructions:["Başlayacağın anı ve o anda gerçekten deneyeceğin davranışı belirt.","Seçtiğin an geldiğinde gerçekte ne yaptığını kaydet."],prompts:[],suggestions:{action:["İşe yarayan tek bir cümle yaz","Dikkatle dinlemek için tek bir soru sor","İşe yarayan küçük bir adımı tamamla"],minimum:["Taslağıma işe yarayan bir cümle ekle","Verilen bir yanıtı sonuna kadar dinle","İşe yarayan tek bir kısmı bitir"],cue:["Öğle yemeğinden sonra masama döndüğüm anda","Çantamı yere bıraktığım anda","Akşam genellikle işe başladığım anda"],place:["Genellikle kullandığım masa veya tezgâhta","Güvenle konuşabildiğimiz her zamanki yerde"],fallback:["Cümleyi yazmak yerine sesle yazdır","Bir sonraki uygun başlama anını kullan","Yapacağım iş için somut yardım iste"],observation:["Cümleyi gerçekten yazıp yazmadığım","Seçtiğim an geldiğinde ne yaptığım","Eski davranışımın sonraya bıraktığı iş"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan tek bir cümle yaz",minimum:"Taslağıma işe yarayan bir cümle ekle",minutes:2,cueHint:"Öğle yemeğinden sonra masama döndüğüm anda",placeHint:"Genellikle kullandığım masa veya tezgâhta",obstacleHint:"Dikkatimi her zamanki gibi dağıtan şeye ulaşmak daha kolay.",fallbackHint:"Cümleyi yazmak yerine sesle yazdır",observationHint:"Cümleyi gerçekten yazıp yazmadığım"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-1-decision",scenario:"Leyla öğle yemeğinden sonra yazmayı planladı ama telefona daldı. Şimdi beş dakikası var. Rapor dosyası açık.",question:"Hangi adımla işe yarayan bir denemeye başlar?",options:[{id:"identity-1-redesign-day",text:"Öğleden sonrası için daha sıkı bir program hazırlasın. Ancak yeni programın tamamını bitirdikten sonra rapora başlasın.",feedback:"Program yapmak ileride yardımcı olabilir. Şimdi ise yapılabilecek bir denemenin önüne daha fazla hazırlık koyuyor. Öğle yemeğinden sonraki başlama anını belirt. İşe yarayan bir cümle yaz ve önüne ne çıktığını kaydet."},{id:"identity-1-test-cue",text:"Öğle yemeğinden sonra ne olduğunu söylesin. Rapora tek bir cümle yazıp başladığı anı kayda eklesin.",feedback:"Bu seçim, gerçek ortamda başka bir davranışı deniyor. Cümle işe katkı sağlıyor. Not da başlama anını gösteriyor. Bir deneme bilgi verir. Bütün kişiliğinin değiştiğini kanıtlaması gerekmez."},{id:"identity-1-change-break",text:"Yarın yazmayı öğle yemeğinden önceye alsın. Bugün kalan beş dakikayı bu yeni planı gözden geçirmeye ayırsın.",feedback:"Sorun öğle yemeğinin saatiyse başlama anını değiştirmek işe yarayabilir. Burada ise hâlâ beş dakikalık gerçek bir deneme mümkün. Yeni programın daha uygun olduğuna karar vermeden önce tek bir cümle dene ve başladığın anı kaydet."}],bestOptionId:"identity-1-test-cue"}},carry:{takeaway:"Tek bir ortamda tek bir davranışı değiştir. Ne olduğunu açıkça yaz.",followUp:{questionId:"identity-1-return",question:"Seçtiğin an geldiğinde, alışık olduğun davranış yerine gerçekte ne yaptın?",observationPrompt:"O anda ne yaptığını söyle. Seçtiğin an hiç gelmediyse bunu kaydet.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Bir davranış, bütün kişiliğin değildir",paragraphs:["Wood ve Rünger’in derlemesi, alışkanlıkları tekrarlanan ortamlarla ilişkili, yinelenen davranışlar olarak anlatır [I06]. Bir ortam, bilinçli seçimlerin yanında alışık olduğun bir davranışı da harekete geçirebilir. Bu, her düşüncenin, ruh hâlinin veya zor günün otomatik bir program olduğunu söylemekten daha sınırlı bir iddiadır. Bu ders, ortadan kaldırman gereken bir “eski sen” aramıyor. Gözle görülebilen tek bir davranışı soruyor.","Günlük tutulan araştırmada 70 ve 209 kişilik öğrenci örneklemleri vardı [I07]. Bildirdikleri davranışların sırasıyla %35’i ve %43’ü neredeyse her gün, aynı yerde yapılan alışkanlık tanımına uyuyordu. Bu oranlar bütün yetişkinleri anlatmaz. Zihnin başka yere kaydığı zamanın yüzdesi de değildir. Davranışlardan örnek toplamak burada bir değerlendirmeydi. Kimliği değiştirdiği gösterilmiş bir tedavi değildi.","ODA’nın başlama anı ve davranış notu, eğitim için hazırlanmış bir uyarlamadır. Sıradaki seçimine yarayacak ayrıntıyı tutman yeterli. Ruh hâlinin aynı kalması veya öğleden sonranın kusurlu geçmesi, doğru anlattığın denemeyi geçersiz kılmaz."]},{heading:"Seçtiğin alternatif gerçekten bir işe yarasın",paragraphs:["Gollwitzer ve Sheeran’ın derlemesi, 8.461 kişinin katıldığı 94 bağımsız testi birleştirdi [I01]. Belirli “şu olursa bunu yaparım” planlarının hedefe ulaşmaya ortalama katkısı bulundu. Kanıtlar, farklı hedefler ve yöntemlerle yapılmış 83 deneysel ve 11 ilişkisel testi içeriyordu. Bu sonuç, ODA’nın tam bu ders sırasının kişinin kimliğini değiştirdiğini göstermiyor.","Bu denemede, tanıyabileceğin bir olayı yapabileceğin bir davranışla birleştir: öğle yemeğinden sonra döndüğünde rapora işe yarayan bir cümle yaz. Gerçekten karşılaştığın bir an belirt. Sadece uygulamayı açmak veya malzeme düzenlemek yerine istediğin yola katkısı olan bir alternatif seç. Bunlar hazırlık olabilir. Ama yaptığın uygulamanın adını doğru koy. Hazırlığı yazma işi gibi gösterme.","Alışık olduğun her davranışı kesmek zorunda değilsin. Hayatına yarayan düzenleri koru. Bulunduğun koşullarda önce güvenlik, dinlenme veya yardım gerekiyorsa bilinçli olarak onu seç. Başka bir düzen eklemeden önce bu tek denemende ne olduğunu gözden geçir."]}],sourceIds:["identity-wood-runger","identity-wood-everyday","identity-gollwitzer"]}},{schemaVersion:2,revision:2,id:"identity-2",courseId:"identity",locale:"tr",title:"Kaygın geçmedi mi? Yine de adımını seç",goal:"Gündelik bir duygu sürerken, aynı başlama anında işe yarayan davranışını dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Başlamak için kaygının geçmesini mi bekliyorsun? Seçtiğin adımı güvenli bir ortamda dene.",reason:{id:"identity-2-reason",label:"Bu duygunun geçmesini beklerken senin için önemli neyi erteliyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Gündelik kaygım sürerken işe başlamak","Benim için değerli bir akşamı korumak","İhtiyaçlarımı gizlemeden bir yanıt vermek"]},why:{id:"identity-2-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin başlama anına ve davranışa dön. Tanıdık bir duygu, fark edebileceğin bir şeydir. Kişiliğinin değişmez olduğunu kanıtlamaz. Duyguyu adlandırmaya dair araştırma sınırlı: küçük bir çalışmada yüzlerdeki duyguyu adlandırmak, beyinde ölçülen yanıtı değiştirdi. Çalışma, senin kendi kaygının geçip geçmediğini sınamadı. Ölçülen beyin yanıtıyla günlük yaşadığın duyguyu aynı şey sayma.","Adlandırmayı bir tarif olarak kullan: “Şu an kaygı var.” Bu kaygı gerçek bir ihtiyaca mı işaret ediyor, önce ona bak. Sonra ne yapacağını seç. Kaygın sürerken cümleni yazabilirsin. Kaygılandığın sorun için bir şey yapman gerekiyorsa yardım isteyebilirsin. Ardından daha sakin hissetmesen bile, yaptığın yararlı adım yine yapılmış olur."],example:{title:"Leyla kaygılıyken yazmaya başlıyor",text:"Perşembe günü öğle yemeğinden sonra Leyla yine aynı rapor için kaygılanıyor. Gereken sayıların elinde olduğunu kontrol ediyor. Kaygısını adlandırıp sıradaki işe yarayan cümlesini yazıyor. Hâlâ her şeyi yeniden kontrol etmek istiyor. Yazdığı cümleyi ve kaygının sürdüğünü kaydediyor. Yazma işini denedi. Duygunun bir alışkanlık olduğunu kanıtlamadı."}},move:{invitation:"Aynı denemeyi sürdür. İşine yarayacaksa gündelik duygunu adlandır. Sonra seçtiğin davranışı yap.",instructions:["Buna gündelik kaygı demeden önce gerçek bir sorun var mı, kontrol et.","Denemeni yaparken duygunun sürmesine izin ver."],prompts:[],suggestions:{action:["Sıradaki işe yarayan cümlemi yaz","Gündelik suçluluk duygum sürerken karşımdakini dinle","İhtiyacım olan somut yardımı iste"],minimum:["Taslağıma işe yarayan bir cümle ekle","Dikkatle dinlemek için tek bir soru sor","Tek bir somut yardım isteği gönder"],cue:["Başlama anımda kaygı belirdiğinde","Acil ihtiyacı kontrol ettikten sonra","Bir sonraki güvenli fırsatımda"],place:["Genellikle kullandığım masa veya tezgâhta","Birlikte güvenle bulunabildiğimiz bir yerde"],fallback:["İşe yarayan bir cümleyi sesle yazdır","Önce gerçekten var olan sorunla ilgilen","Bunun yerine destek almayı seç"],observation:["Kaygım sürerken adım atıp atmadığım","Karşılanmamış gerçek bir ihtiyaç olup olmadığı","Gerçekte ilettiğim istek veya verdiğim yanıt"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sıradaki işe yarayan cümlemi yaz",minimum:"Taslağıma işe yarayan bir cümle ekle",minutes:2,cueHint:"Başlama anımda kaygı belirdiğinde",placeHint:"Genellikle kullandığım masa veya tezgâhta",obstacleHint:"Bir şey yapmadan önce bu duygunun geçmesini istiyorum.",fallbackHint:"İşe yarayan bir cümleyi sesle yazdır",observationHint:"Kaygım sürerken adım atıp atmadığım"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-2-decision",scenario:"Leyla’nın beş dakikası var. Elindeki sayılar onaylı tabloyla uyuşuyor. Yazacağı cümle yeni bir hesaplama içermiyor. Yine de kaygısı sürüyor.",question:"Bu ana hangi davranış daha iyi uyar?",options:[{id:"identity-2-recheck",text:"Cümleyi yazmadan önce kendinden daha emin hissetmek için elindeki sayıları bir kez daha kontrol etsin.",feedback:"Bilgi eksikse bir kontrol daha işe yarayabilir. Burada gereken sayılar zaten kontrol edildi. Yeniden bakmak, yapılabilecek yazma denemesini erteliyor. Daha sakin hissetmenin güvenilir bir başlama işareti olacağını da göstermiyor."},{id:"identity-2-provisional-check",text:"Geçici bir taslak cümle yazsın. Cümleyi raporda tutmadan önce bir iş arkadaşından içindeki sayıyı doğrulamasını istesin.",feedback:"Sayı belirsizse geçici cümle ve ikinci kontrol yardımcı olur. Burada ise onaylı tablo cümleyi zaten destekliyor. Bir yanıt daha beklemek, bilinen bir eksiği gidermeden işe yarayan cümleyi raporda tutmayı geciktiriyor."},{id:"identity-2-act-with-feeling",text:"Kaygısını adlandırsın. İşe yarayan tek bir cümle yazsın. Endişesinin başka bir adım gerektirip gerektirmediğini kayda eklesin.",feedback:"Leyla bu seçenekte duygusunu yok saymıyor, neye işaret ettiğine bakıyor. Duyguya otomatik olarak her şeyi durdurma hakkı vermiyor. Uygulama, yazdığı cümle. Gerçek bir sorun ortaya çıkarsa sıradaki adım somut yardım istemek olabilir."}],bestOptionId:"identity-2-act-with-feeling"}},carry:{takeaway:"Bir duygu sürerken de işe yarayan, güvenli bir davranışı seçebilirsin.",followUp:{questionId:"identity-2-return",question:"Adımın sırasında duygu sürdü mü? Karşılanmamış gerçek bir ihtiyaca işaret etti mi?",observationPrompt:"Süren duyguyu ve varsa gösterdiği ihtiyacı söyle. Belirgin bir ihtiyaç yoksa onu belirt.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Duyguyu adlandırma araştırmasında gerçekten ne ölçüldü?",paragraphs:["Lieberman ve arkadaşları, beyin görüntüleme cihazında duygu gösteren yüzlere bakan 30 sağlıklı yetişkini inceledi [I10]. Duygu sözcüğü seçmek, yüzün cinsiyetine uygun bir isim seçmeye göre amigdalada daha düşük etkinlikle sonuçlandı. Bu, laboratuvarda ölçülen bir beyin farkıdır. Kendi sıkıntını adlandırmanın onu azalttığını veya haftalar boyunca ruh hâlini iyileştirdiğini gösteren bir bulgu değildir. Sonucun sınırı burada kalır.","ODA, kısa bir duygu adını isteğe bağlı bir tarif olarak kullanıyor. Araştırma bu başlama anını, senin seçtiğin davranışı veya kimlik üzerine bir kursu sınamadı. Bir katkısı yoksa adlandırmayı atla. Her duyguyu düzeltmek zorundaymışsın gibi davranma. Yas, haksızlığa duyduğun öfke ve tehlike anındaki korku farklı bir yanıt gerektirebilir. Bunların verdiği bilgiyi gözden kaçırma.","Gözleminde yine aynı davranışı değerlendir. Onu yaptın mı, yardım gerekti mi, gerçek bir sorun planı değiştirdi mi? Bir kayıt, zor bir duyguyu ve yararlı bir davranışı birlikte anlatabilir. Birinin diğerine neden olduğunu söylemek zorunda değildir."]},{heading:"Sorumluluğu silmeden destek alabilirsin",paragraphs:["Breines ve Chen, çoğunlukla öğrencilerle veya internetten katılan kişilerle dört kısa deneyde şefkatli yanıtları sınadı [I11]. Bazı sonuçlar, hemen ardından kendini geliştirme isteğini destekledi. Bir çalışmada katılanlar zor bir sınavdan sonra, hiçbir uygulama almayan gruptan daha uzun süre ders çalıştı. Sonraki sınav notlarında istatistiksel olarak anlamlı fark bulunmadı. Öz saygı grubuyla karşılaştırma ise yalnızca sınırda bir bulguydu.","Bu kanıt, kalıcı kimlik değişimini veya anlayışlı davranmanın her zaman üstün olduğunu göstermez. Ama yeniden denemeden önce her zaman sert davranmak gerektiği varsayımını sorgulatır. Bu derste duyguyu tarif edip seçtiğin işe devam etmek, ODA’nın uyarlamasıdır. Araştırmada sınanan şefkatli yazma alıştırmasının kendisi değildir. İkisini aynı uygulama gibi sunamayız.","Kendi payını gözden kaçırmadan kendine adil davran. Beceri eksikse öğrenmek gerekir. Karşılanmamış bir ihtiyaç için yardım gerekebilir. Kendine hakaret etmeden adım atabilirsin. Ara verdiğinde de bunu bütün kişiliğinin başarısızlığı saymadan o arayı kaydedebilirsin."]}],sourceIds:["identity-lieberman","identity-breines"]}},{schemaVersion:2,revision:2,id:"identity-3",courseId:"identity",locale:"tr",title:"Geç mi fark ettin? Sıradaki adımın işe yarasın",goal:"Dikkatin dağıldıysa seçtiğin işe dön. Davranışın zarar verdiyse kendi payına düşeni düzelt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Telefona daldın mı, ağzından sert bir söz çıktı mı? Sıradaki cümlen hâlâ işe yarayabilir.",reason:{id:"identity-3-reason",label:"Aynı denemede nerede işe dönmek veya kendi davranışını düzeltmek gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Öğleden sonram bitmeden işime dönmek","Verdiğim sert bir yanıtı düzeltmek","Yararlı adımımı hâlâ yapabilmek"]},why:{id:"identity-3-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Dikkatinin dağıldığını fark etmek başka, işe dönmek başka. Seçtiğin başlama anını ve davranışı koru. Geç fark ettiğinde ne yapacağını da belirle: “İşten koptuğumu fark edersem işe yarayan en küçük adımımı yapacağım.” Araştırmalarda belirli bir durumu belirli bir davranışa bağlayan planlar, hedefe ulaşmayı ortalama olarak artırdı. Ama sadece fark etmiş olmak, işin yapıldığını göstermez.","Verdiğin yanıt birini incittiyse bunu kendi içinde fark etmen, düzeltme değildir. Güvenli bir ortamda kendi payını kabul et. Bir cümleyi yeniden söyle. Kimse zarar görmediyse işe dön. Yalnızca fark ettiğin anları değil, ardından ne yaptığını kaydet. Bütün günü mahvolmuş saymadan sıradaki davranışını değiştirebilirsin."],example:{title:"Leyla işten koptuğunu geç fark ediyor",text:"Saat 13.42. Leyla yazmak yerine on iki dakikadır telefona baktığını fark ediyor. Akışı kapatıp raporuna işe yarayan bir cümle ekliyor. Sonra iş arkadaşına gönderdiği sert mesajı fark ediyor. Kısa bir mesajla üslubunu düzeltiyor. Bu iki adım da kaybolan zamanı geri getirmiyor. Ama ikisi de kaydına yazabileceği somut davranışlar."}},move:{invitation:"Aynı davranışı koru. Durumu geç fark ettiğinde ardından ne yapacağını seç.",instructions:["İşe yarayan en küçük adıma dön veya kendi zararlı davranışını düzelt.","Fark ettikten sonra gerçekte ne yaptığını kaydet."],prompts:[],suggestions:{action:["İşe yarayan cümleme geri dön","Bir cümleyi saygılı biçimde yeniden söyle","Gönderdiğim sert mesajı düzelt"],minimum:["Şimdi işe yarayan tek bir cümle ekle","Sert cümlemi kabul edip yeniden söyle","Düzeltme için tek bir açık mesaj gönder"],cue:["Telefona daldığımı fark ettiğim anda","Sesimdeki sertliği duyduğum anda","Güvenli bir kesinti sona erince"],place:["Genellikle kullandığım masa veya tezgâhta","Güvenle kullanabildiğim mesajlaşma kanalında"],fallback:["İşe yarayan daha kısa bir cümle kullan","Düzeltme için daha güvenli bir iletişim yolu seç","İşe yeniden başlamak için yardım iste"],observation:["Fark ettikten sonra gerçekte ne yaptığım","Kendi davranışımı gerçekten düzeltip düzeltmediğim","Bu davranışı hangi anda fark ettiğim"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan cümleme geri dön",minimum:"Şimdi işe yarayan tek bir cümle ekle",minutes:2,cueHint:"Telefona daldığımı fark ettiğim anda",placeHint:"Genellikle kullandığım masa veya tezgâhta",obstacleHint:"Dikkatim dağıldıktan sonra ancak fark ediyorum.",fallbackHint:"İşe yarayan daha kısa bir cümle kullan",observationHint:"Fark ettikten sonra gerçekte ne yaptığım"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-3-decision",scenario:"Güvenli bir konuşma sırasında Leyla bir iş arkadaşına sert çıkıyor. Konuşmaları sürerken kendi sesindeki sertliği fark ediyor.",question:"Davranışını fark etmesini hangi adım anlamlı kılar?",options:[{id:"identity-3-repair",text:"Sert söylediği cümleyi kabul etsin. Konuşma hâlâ sürerken anlatmak istediğini saygılı bir cümleyle yeniden söylesin.",feedback:"Böylece fark etmesi somut bir işe yarıyor. Leyla kendi üslubunun sorumluluğunu alıyor, farklı bir yanıt deniyor. Düzeltme denemesinin gerçekten yapılmış olması için iş arkadaşının onu affetmesi gerekmiyor."},{id:"identity-3-private-catch",text:"Kendi içinde durup fark ettiğini kaydetsin. Sonra bir dahaki konuşmada daha sabırlı davranmaya odaklanarak bu konuşmayı sürdürsün.",feedback:"Fark etmek bilgi verir. Ama sert cümle bu konuşmayı zaten etkiledi. Düzeltmek güvenli ve uygunsa kısaca kendi payını kabul edip yeniden söylemek, sadece yarının davranışına değil, şu anki etkiye yanıt verir."},{id:"identity-3-full-explanation",text:"Teslim baskısının neden sesini sertleştirdiğini açıklasın. Ardından üslubuna yeniden dönmeden işle ilgili konuşmaya kaldığı yerden devam etsin.",feedback:"Koşullar gerginliği açıklayabilir, değişmeleri de gerekebilir. Ama bu, kendi davranışını düzeltmenin yerini tutmaz. Önce üslubunu kabul et. Sonra iş yükünü konuş. Karşı tarafın kabul etmesini düzeltmenin şartı yapma."}],bestOptionId:"identity-3-repair"}},carry:{takeaway:"Fark ettiğin an, işe döndüğünde, düzelttiğinde veya daha güvenli bir davranış seçtiğinde işe yarar.",followUp:{questionId:"identity-3-return",question:"Davranışı ne zaman fark ettin? Ardından işe döndün mü, davranışını düzelttin mi?",observationPrompt:"Ne zaman fark ettin? İşe döndün mü, davranışını düzelttin mi, kendini korudun mu? Fırsat olmadıysa belirt.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Geç fark ettiğin an da başlama işaretin olabilir",paragraphs:["“Şu olursa bunu yaparım” planları, belirli bir durumla seçilmiş bir davranışı birleştirir. Gollwitzer ve Sheeran’ın derlemesi, 94 bağımsız testte hedefe ulaşmada ortalama yarar buldu [I01]. Hedefler, uygulama biçimleri ve araştırma yöntemleri farklıydı. Bu sonuç, belirli bir duraklama sözcüğünü, nefes sırasını veya gün içinde kaç kez fark etmen gerektiğini doğrulamıyor.","Bu ders, geç fark etmeyi bir başka olası başlama anı olarak ekliyor: telefona daldığını fark edersen seçtiğin yararlı cümleyi yaz. Davranışın hâlâ kurstaki aynı denemenin parçası. İçinden söylediğin bir işaret sözcüğü isteğe bağlı bir hatırlatmadır. Geliştirmek istediğin asıl davranışın kendisi değildir. İşe dönmeden önce nefes alıştırması yapman veya sakin hissetmen gerekmiyor.","Wood ve Rünger, alışkanlıkların bilinçli süreçlerle birlikte işlediğini anlatır [I06]. Bu, kusurlu bir düzenin içinde bilinçli bir davranışa da yer bırakır. Her dikkat dağılması alışkanlıktı demek değildir. Gördüğün şeyi anlat. Bu işareti gerçekten bulunduğun ortamda tanıyıp tanıyamadığını dene. Başlama anın, kâğıt üzerindeki hâliyle değil, yaşadığın durumla uyuşmalı."]},{heading:"Fark et, sonra ortaya çıkan sonuçla ilgilen",paragraphs:["Kaydın fark etmeyi, işe dönmeyi ve düzeltmeyi ayrı tutmalı. Harkin ve arkadaşları, ilerleme takibi üzerine 138 rastgele kontrollü çalışmayı inceledi [I02]. Takip uygulamaları hedefe ulaşmayı ortalama olarak artırdı. Yanlılığa göre düzeltilmiş tahmin ise daha küçüktü. Derleme, yalnızca fark ettiğin anları saymanın ilişkilerini değiştirdiğini göstermiyor. Kendin için yazdığın her notu paylaşman gerektiğini de söylemiyor.","Bu ODA uyarlamasında, fark ettikten sonra yaptığın davranışı kaydet. “Sesimdeki sertliği yakaladım” ile “Sertliğimi kabul edip isteğimi yeniden söyledim” farklı gerçeklerdir. Asıl işin bölündüyse geri dönüp yaptığın yararlı kısmı kaydet. Sen zarar vermediysen özür dilemen gerekmez. Kaydın seni her durumda sorumlu ilan etmesin.","Güvenli olmayan bir ilişkide önce korunmak gerekir. Seni tehdit eden birine ulaşmak, onu affetmek veya açıklama yapmak zorunda değilsin. Uygunsa sınır koymayı veya destek istemeyi seç. Bu davranışların adını doğru koy. Her arayı başarılı bir düzeltme sayma. Ara vermiş olman ile bir şeyi düzeltmiş olman ayrı kalabilir."]}],sourceIds:["identity-gollwitzer","identity-wood-runger","identity-harkin"]}},{schemaVersion:2,revision:2,id:"identity-4",courseId:"identity",locale:"tr",title:"Hep hazırlık mı yapıyorsun? Yaptığın iş kanıt olsun",goal:"En küçük adımın, seçtiğin davranışı gerçekten denemeni sağlıyor mu? Kontrol et, sonra bir kez dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yine kusursuz bir plan var, taslak hâlâ yok mu? İşe yarayan tek bir adımı kanıt olarak göster.",reason:{id:"identity-4-reason",label:"Bu en küçük adım becerini geliştiriyor mu, yoksa onu sonraya mı bırakıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["İşin kendisini gerçekten denemek","En küçük adımımı anlamlı tutmak","Sadece gerçekte ne yaptığımı anlatmak"]},why:{id:"identity-4-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Son denemene bak. James Clear, davranışları bir kimliğe verilen “oylar” diye anlatır. Bu bir benzetme, bilimsel yasa değil. Önce kimliğinin değişmesi gerektiğini söylemeden de bu benzetmeyi kullanabilirsin. Şunu sor: Bu davranış, seçtiğin yol için gereken bir şeyi gerçekten yapmanı sağlıyor mu? Sadece hazırlanıyor olabilir misin?","Taslağı açman, açtığını gösterir. İşe yarayan bir cümle yazman, yazdığını gösterir. İkisinin de amacı olabilir. Ama hazırlığa hazırlık de. En küçük adımın haftana sığsın, aynı zamanda bir katkısı olsun. Gerçek bir denemeden sonra sadece o denemenin kanıtını anlat. “Bir cümle yazdım” demek için özgüveninin kalıcı olarak değiştiğini iddia etmen gerekmez."],example:{title:"Leyla işe yarayan en küçük adımı seçiyor",text:"Cuma günü Leyla beş dakika başlıkları düzenliyor. Rapora hâlâ metin yazmadı. Denemesine bakıp en küçük adımı bir başlığın altına işe yarayan tek bir cümle yazmak olarak değiştiriyor. Bırakmadan önce onu yazıyor. Cümlenin düzeltilmesi gerekiyor. İsteğe bağlı notuna “Artık disiplinli bir insanım” yerine “Bugün bir cümle yazdım” diyor."}},move:{invitation:"Kaydettiğin en küçük adıma bak. Sadece hazırlıksa adını dürüstçe koy veya asıl davranışı denemeyi seç.",instructions:["Seçtiğin yolun gerektirdiği davranışın işe yarayan küçük bir kısmını yap.","Ardından yalnızca gerçekten tamamladığın davranışı anlat."],prompts:[],suggestions:{action:["Rapora işe yarayan tek bir cümle yaz","Seçtiğim beceriyi gerçekten bir kez dene","Düzeltmek için saygılı bir cümle kullan"],minimum:["İşe yarayan tek bir cümle ekle","Bir beceri denemesini tamamla","Kendi davranışımı gerçekten bir kez düzelt"],cue:["Üzerinde çalıştığım taslağı açtığım anda","Bir sonraki uygulama anım geldiğinde","Kendi davranışımı güvenle düzeltebildiğim anda"],place:["Üzerinde çalıştığım asıl taslağın içinde","Genellikle pratik yaptığım yerde"],fallback:["İşe yarayan bir cümleyi sesle yazdır","Asıl denemeyi daha küçük bir adımla yap","Hazırlık yaptıysam bunu hazırlık olarak kaydet"],observation:["Gerçekten tamamladığım davranış","En küçük adımımın istediğim yola katkısı","Hangi hazırlıkların hâlâ beklediği"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Rapora işe yarayan tek bir cümle yaz",minimum:"İşe yarayan tek bir cümle ekle",minutes:2,cueHint:"Üzerinde çalıştığım taslağı açtığım anda",placeHint:"Üzerinde çalıştığım asıl taslağın içinde",obstacleHint:"Asıl davranışı yapmak yerine hazırlanmak daha kolay geliyor.",fallbackHint:"İşe yarayan bir cümleyi sesle yazdır",observationHint:"Gerçekten tamamladığım davranış"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-4-decision",scenario:"Leyla yorgun. Beş dakikası var ve rapora metin yazmak istiyor. Başlıkları hazır. Sıradaki cümlede kullanacağı sayı da kaynağıyla zaten uyuşuyor.",question:"Hangi en küçük adım şimdi yararlı bir iş çıkarır?",options:[{id:"identity-4-organize",text:"Yarın yazmaya başlaması daha kolay olsun diye elindeki notları daha açık bir klasör düzenine göre yeniden yerleştirsin.",feedback:"Düzenlemek sonraki yazma işini destekleyebilir. Burada ise notlar ve başlıklar zaten hazır. Daha fazla hazırlık, Leyla’nın çalışmak istediği beceriyi erteliyor. Yine de bunu seçerse adını hazırlık olarak koysun."},{id:"identity-4-write-unit",text:"Asıl rapora bir taslak cümle yazsın. Sonra o anki gücüne göre durmanın uygun olup olmadığına karar versin.",feedback:"Bu küçük adımda istediği davranışı uyguluyor, elindeki zamanı kullanıyor. Tek bir cümle yazıldığını kanıtlıyor. Kimliğinin değiştiğini değil. Cümleyi etkileyici hâle getirmek zorunda olmadan çalışmayı bırakabilir."},{id:"identity-4-verify-support",text:"Kaynak gösterdiği sayıyı yeniden kaynağından kontrol etsin. Yarın yazacağı cümle için doğrulanmış bir not bırakıp bugün çalışmayı bitirsin.",feedback:"Bilginin dayanağı belirsizse doğrulamak yararlıdır. Bu sayı zaten kontrol edildi. Aynı hazırlığı tekrarlamak bu akşamki yazma zamanını tüketir. Dayanağı olan tek bir taslak cümle, raporu şimdi ilerletebilir."}],bestOptionId:"identity-4-write-unit"}},carry:{takeaway:"Kanıtın, yaptığın davranışı anlatsın. Hazırlık ile uygulamayı birbirinden ayrı tut.",followUp:{questionId:"identity-4-return",question:"En küçük adımın gerçekte neyi gösterdi? Seçtiğin yola bir katkısı oldu mu?",observationPrompt:"En küçük adımının gösterdiği davranışı ve istediğin yola katkısını anlat.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Kimlik benzetmesinin sınırları var",paragraphs:["Clear’ın kendi yazısı, istenen bir kimliği ve onu destekleyen küçük davranışları uygulamaya dönük bir çerçeve olarak sunar [I15]. Önce kimliği değiştirmenin gerekli veya üstün olduğunu kanıtlayan kontrollü bir deney değildir. Davranışı oy gibi anlatmak akılda kalabilir. Ama akılda kalması, onu bilimsel bir açıklamaya dönüştürmez. Bu benzetmeyi kullanmak senin seçimin olarak kalır.","Bandura’nın öz yeterlik çerçevesi, belirli bir işi yapabileceğine dair beklentiyi anlatır [I17]. Kendi başardıkların bu inancın kaynaklarından biridir. Başkalarını gözlemek, cesaretlendirilmek ve bedenden gelen bilgiler de buna katkı sağlar. Bu çerçeve tek bir davranışı insan olarak değerinin ölçüsüne dönüştürmez. Bütün kişiliğin hakkında verilmiş bir hüküm de saymaz.","ODA’nın isteğe bağlı kanıt cümlesi sınırlı kalır: “İşe yarayan bir cümle ekledim” veya “İsteğimi ilettim.” Denenmemiş bir plan ve doğru quiz yanıtı bu davranışların yapıldığını göstermez. Kimliğinle ilgili hiçbir cümle kurmadan da aynı somut denemeye devam edebilirsin. Kaydın, yaptığını anlatmaya yeter."]},{heading:"Davranış ve kimlik farklı sonuçlardır",paragraphs:["Rhodes ve arkadaşları, 4.939 yetişkini kapsayan 40 deneysel veya yarı deneysel etkiyi inceledi [I19]. Fiziksel etkinliğe ilişkin kimlik, ortalama olarak az değişti: etki g = 0,18’di. Davranışın incelendiği 30 etkilik alt örneklemde fiziksel etkinlik için daha büyük bir ortalama etki bulundu. Ama örneklemler ve sonuçlar farklı. Bu sayılar, davranışın değişmesine kimliğin neden olduğunu kanıtlamaz.","Çalışmalar fiziksel etkinlikle ilgili. Sonuçlar farklılık gösteriyor ve yayın yanlılığı olası. Bütün kişiliğin dönüşmesini, Clear’ın oy yöntemini veya bu rapor yazma denemesini doğrulamıyorlar. Zorlanman da hedefin mutlaka peşinden gitmeye değer olduğunu göstermez. Bir beceri eksiğini, yetersiz kaynakları veya planı değiştirmen gerektiğini gösterebilir. Güçlüğün kendisi devam etme zorunluluğu yaratmaz.","En küçük adımının neye katkı sağladığını kaydına bakarak seç. Gücüne uyuyorsa küçük kısmı koru. Ancak kendi isteğinle büyüt veya uymayan hedefi değiştir. Amaç hayatında işe yarayan bir uygulama yapmak. Sembolik oylar biriktirmek değil."]}],sourceIds:["identity-clear-identity","identity-task-belief","identity-activity-identity"]}},{schemaVersion:2,revision:2,id:"identity-5",courseId:"identity",locale:"tr",title:"Yeterince prova yaptın mı? Şimdi gerçekte dene",goal:"İşine yarayacaksa kısa bir hazırlıkla tek bir engeli ele al. Ardından seçtiğin aynı davranışı dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kusursuz başlangıcı hayal etmek, başlamanın yerini mi alıyor? Hazırlığın sonunda gerçekten bir deneme yap.",reason:{id:"identity-5-reason",label:"Kısa bir prova, hangi engelle karşılaştığında sana yardımcı olabilir?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek başlama anıma hazırlanmak","Kusursuz yapmadan önce bir kez denemek","Prova ile gerçek davranışı ayrı tutmak"]},why:{id:"identity-5-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Prova hazırlıktır. Asıl davranışın kendisi değildir. Davranışı hayal etmeye dair araştırmalarda ortalama bir davranış yararı bulundu. Ama hangi hayal etme biçiminin daha iyi olduğu netleşmedi. Sonucu hayal etmek yerine adımları hayal etmenin üstün olduğunu kanıtlamıyor. Belirli süre yapılan bir kimlik meditasyonunun kişiliğini değiştirdiğini de göstermiyor. Hazırlık ile gerçekte yaptığını ayrı değerlendirmek gerekir.","Kaydında bir hazırlık eksiği varsa provayı kullan. İlk adımı ve çıkabilecek bir engeli anlat veya hayal et. Sonra davranışını gerçek başlama anında dene. Gözünde canlandırmak rahatsız ediyorsa veya bunu yapamıyorsan sözcükleri kullan ya da bu kısmı atla. Hazırlığı ayrı kaydet. Denemen pek akıcı olmayabilir. Sonucu da hâlâ belirsizdir."],example:{title:"Leyla’nın ilk cümlesi kusursuz değil",text:"Pazartesi rapor çalışmasından önce Leyla nasıl başlayacağını anlatıyor: son cümlesini okuyup kulağa acemi işi gelse de bir cümle ekleyecek. Gözleri açıkken kısaca bu geçişin provasını yapıyor. Öğle yemeği sonrası başlama anında cümleyi ekliyor. Hayal ettiğinden daha az akıcı. Kısa hazırlığını ve gerçekte yazdığı cümleyi ayrı ayrı kaydediyor."}},move:{invitation:"Hazırlık yardımcı olacaksa kısa tut. Denemenin kaydına, gerçekte yaptığın işi yaz.",instructions:["İlk yararlı adımın provasını yalnızca gerekiyorsa yap.","Gerçek başlama anında dene. Yaptığın hazırlığı ayrı kaydet."],prompts:[],suggestions:{action:["Asıl taslağıma sıradaki cümleyi ekle","Hazırladığım adımı bir kez dene","Seçtiğim küçük uygulamayı tamamla"],minimum:["Taslağın içine tek bir cümle yaz","Seçtiğim anda belirlediğim adımı at","Gerçek uygulamanın küçük bir kısmını bitir"],cue:["Öğle yemeğinden sonra yazmaya başladığım anda","Provasını yaptığım başlama anı geldiğinde","Her zamanki başlama işaretim ortaya çıktığında"],place:["Üzerinde çalıştığım asıl taslağın içinde","Genellikle güvenle adım attığım yerde"],fallback:["Provayı atla, işe yarayan bir cümle yaz","Sözcüklerle hazırlan, öğle yemeği sonrasında dene","Eksik olan becerim için yardım iste"],observation:["Gerçek denemede ne olduğu","Beklediğim engelin ortaya çıkıp çıkmadığı","Yalnızca hazırlık olan kısım"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Asıl taslağıma sıradaki cümleyi ekle",minimum:"Taslağın içine tek bir cümle yaz",minutes:2,cueHint:"Öğle yemeğinden sonra yazmaya başladığım anda",placeHint:"Üzerinde çalıştığım asıl taslağın içinde",obstacleHint:"Asıl davranışa başlamak yerine tekrar tekrar prova yapıyorum.",fallbackHint:"Provayı atla, işe yarayan bir cümle yaz",observationHint:"Gerçek denemede ne olduğu"},stopRule:"Travma içeren sahneleri atla. Sıkıntı veren canlandırmayı durdur. Sözcükleri, desteği veya doğrudan güvenli bir denemeyi seç.",accessibleAlternative:"Gözlerini açık tut veya canlandırmayı atla. Sözcüklerle hazırlanmak için “Bunu uyarla” seçeneğini kullan. Gerçekte ne zaman deneyeceğini belirt."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-5-decision",scenario:"Leyla raporun ilk noktasını ve nasıl yazacağını biliyor. On dakikası var. Kendinden emin bir çalışma hayal etmesi, son iki kez başlamasını geciktirdi.",question:"Hazırlık ile uygulamayı hangi seçim daha iyi bağlar?",options:[{id:"identity-5-direct-attempt",text:"Daha fazla prova yapmadan rapora başlama anında tek bir cümle eklesin. Başlarken gerçekten nerede zorlandığını kaydetsin.",feedback:"Kaydı, sorunun ilk adımı bilmemesi değil, provayı uzatması olduğunu gösteriyor. Bildiği cümleyi denemek bu engeli ele alır. Belirli bir hazırlığın yararlı olup olmayacağına karar vermeden önce gerçek denemenin gösterdiği zorluğu kaydet."},{id:"identity-5-timed-process",text:"İki dakika boyunca sorunsuz bir başlangıcın provasını yapsın. Ardından çalışma zamanı bitmeden raporuna tek bir cümle yazsın.",feedback:"Süreli prova hazırlığı bitirir ve tanımadığın bir adımı netleştirebilir. Leyla bu adımı zaten biliyor. Prova iki başlangıcını geciktirdi. Doğrudan uygulama, kaydın gerçekten gösterdiği sorunu sınar."},{id:"identity-5-timed-outcome",text:"Bir dakika raporu bitirdiğini hayal etsin. Sonra tek bir cümle yazıp başlamasına neyin yardımcı olduğunu kaydetsin.",feedback:"Bu seçim gerçek deneme içeriyor. Araştırmalar da üstün bir canlandırma biçimi belirlemiyor. Ama burada isteksizlikten kaynaklanan bir eksik görülmedi. Daha fazla canlandırmayı atlamak, Leyla’nın tekrar eden hazırlık gecikmesine daha doğrudan yanıt verir."}],bestOptionId:"identity-5-direct-attempt"}},carry:{takeaway:"Yararlı provanın bir bitişi, ardından da gerçekten deneyebileceğin bir fırsatı vardır.",followUp:{questionId:"identity-5-return",question:"Hazırlığınla seçtiğin başlama anında yaptığın deneme arasında ne farklıydı?",observationPrompt:"Hazırladığınla o anda olanı karşılaştır. Hazırlığı atlaman da geçerli bir seçim.",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Üstün olduğu gösterilmiş bir canlandırma biçimi yok",paragraphs:["Cole ve arkadaşları 94 rastgele kontrollü çalışmayı, 123 etkiyi ve 5.685 katılımcıyı birleştirdi [I03]. Zihinsel canlandırmanın genel davranış etkisi g = 0,49’du. Bazı alt türlerin tahminleri sayısal olarak daha büyüktü. Ama alt türlerin genel karşılaştırmasında istatistiksel olarak anlamlı fark bulunmadı. Yalnızca süreci hayal eden alt grup sadece beş etki içeriyordu. Bu grubun sonucu belirsizdi.","Örneklemlerin çoğu öğrencilerdi. Birçok çalışma yanlılık hakkında sınırlı bilgi verdi. Derleme, üstün bir canlandırma türü, daha uzun uygulamanın yararı veya on dakikalık meditasyonla kimlik değişimi belirlemiyor. Bu dersin kısa hazırlığı, seçilmiş bir tasarımdır. İncelenen araştırma uygulamasının kendisi değildir. Araştırmanın genel sonucunu bu kısa hazırlığın garantisi gibi kullanamayız.","Gerçek hazırlık eksiğine göre sözcükleri, canlandırmayı veya hiç prova yapmamayı seç. İşe yarayan ilk adımı tarif etmek, kusursuz bir gelecek sahnesinden daha kolay değerlendirilebilir. Kursun kaydı yine de şunu sormalı: o adımı gerçek ortamda denediğinde ne oldu? Hazırlanmış olman tek başına bu soruyu yanıtlamaz."]},{heading:"Gerçekte yapacağın işe hazırlan",paragraphs:["Toth ve arkadaşlarının 37 çalışmalık derlemesi, hareket becerileri ve görev performansıyla ilgiliydi [I18]. Yanlılığa göre düzeltilmiş küçük bir zihinsel prova etkisi bildirdi: r = 0,131. Bu kanıt, duyguların biyolojisinin değiştiğini, hastalıkların iyileştiğini veya bütün kimliğinin dönüştüğünü göstermez. Prova bir işi destekleyebilir. Yönergenin, malzemelerin veya gerçekten uygulama yapmanın yerini tutmaz.","Belirli “şu olursa bunu yaparım” planları için farklı testlerden, hedefe ulaşmaya dair daha geniş destek var [I01]. Bu ODA denemesinde gerçek bir başlama anını zaten seçtiğin davranışla birleştir. Provayı yalnızca ne yapacağını netleştirmek için kullan. İlk rapor cümlene hazırlanmak ve onu yazmak farklı davranışlardır. Birinden diğerinin de yapıldığını çıkarma.","Travma veya sıkıntı veren anılar içeren sahneleri atla. Gözlerini açık tutabilir, adımları görüntüsüz anlatabilir, yardım kullanabilir veya doğrudan güvenli bir denemeye geçebilirsin. Hazırlık uzayıp duruyorsa onu küçült. Bunun için bir sabah ritüeli daha eklemen gerekmiyor. Hazırlığın ne zaman biteceği belli kalsın."]}],sourceIds:["identity-cole","identity-motor-rehearsal","identity-gollwitzer"]}},{schemaVersion:2,revision:2,id:"identity-6",courseId:"identity",locale:"tr",title:"Başlama anı hep kayıyor mu? Bir koşulu değiştir",goal:"Kayıtlarına bak. Tek bir başlama anını veya malzemeyi değiştir, sonra aynı yararlı davranışı dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kurduğun güzel düzende başlama anı hiç gelmiyorsa ne işe yarar? Bugün tek bir koşulu dene.",reason:{id:"identity-6-reason",label:"Bu davranışa yer açmak için şu an işini kolaylaştıran hangi düzeni değiştireceksin?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçekten gelen bir başlama anını kullanmak","Gereken malzemeyi yakınımda hazır tutmak","Dikkat dağılmasını azaltırken acil iletişimi korumak"]},why:{id:"identity-6-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Yaptığın denemelerin kaydına dön. Seçtiğin an geldi mi? Malzemeler elinin altında mıydı? Belirli bir plan, varsaydığı durum hiç gerçekleşmediğinde aksayabilir. “Şu olursa bunu yaparım” planları ortalama olarak yardımcı olur. Ama başlama anının haftana uyması gerekir. Kâğıt üzerinde açık olması, gerçek hayatında da oluşacağını göstermez.","Alışkanlık araştırmaları, tekrar eden davranışları tekrar eden ortamlarla ilişkilendirir. Çevrenin seçimlerinden güçlü olduğunu ilan etmeden tek bir koşulu değiştir. Davranışını koru. Malzemeyi kullanacağın yere taşı veya güvenilir bir olay seç. Bir kez dene. Hangi adımda ilerledin, nerede takıldın, kaydet. Gerekli araçlara erişimini, acil iletişimi ve ihtiyacın olan düzenleri koru."],example:{title:"Leyla’nın çay molası bir türlü gelmiyor",text:"Leyla öğleden sonraki çaydan sonra yazmayı planladı. Ama toplantılar yüzünden mola tekrar tekrar olmadı. Yalnızca başlama anını değiştiriyor: öğle yemeğinden dönünce masasında hazır bekleyen raporu açıp bir cümle yazacak. Ailesi ulaşabilsin diye telefonu erişilebilir tutuyor. Salı günü seçtiği an geliyor, cümlesini yazıyor. Cümlenin sonunu hâlâ düzeltmesi gerekiyor."}},move:{invitation:"Tek bir kayda bakarak aksayan bir koşulu değiştir. Mevcut davranışını yeni başlama anında dene.",instructions:["Gerçekten karşılaştığın olaylardan birini başlama anı, birini yedek olarak seç.","Bir başlama anını veya malzemeyi değiştir. Sonra yararlı en küçük adımı dene."],prompts:[],suggestions:{action:["Yeni seçtiğim başlama anında yaz","Hazır malzememin yanında uygulama yap","Güvenilir başlama anında seçtiğim davranışı dene"],minimum:["Bu anda işe yarayan bir cümle ekle","Gerçek uygulamanın tek bir kısmını tamamla","İşe yarayan tek bir adım at"],cue:["Öğle yemeğinden döndüğüm anda","Gerekli bir günlük işimi bitirdiğim anda","Bir sonraki güvenilir görüşme anımda"],place:["Hazır bekleyen kendi taslağımın yanında","Erişebildiğim, adımı atabileceğim yerde"],fallback:["Sonraki toplantıdan sonra masamda bir cümle yaz","Elimdeki araçla cümleyi sesle yazdır","Acil arama ve mesajlara erişimi açık tut"],observation:["Yeni seçtiğim başlama anının gelip gelmediği","Gereken malzemenin hazır olup olmadığı","Neyin işe yaradığı, neyin engel çıkardığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Yeni seçtiğim başlama anında yaz",minimum:"Bu anda işe yarayan bir cümle ekle",minutes:2,cueHint:"Öğle yemeğinden döndüğüm anda",placeHint:"Hazır bekleyen kendi taslağımın yanında",obstacleHint:"İlk seçtiğim başlama anı çoğu zaman gelmiyor.",fallbackHint:"Sonraki toplantıdan sonra masamda bir cümle yaz",observationHint:"Yeni seçtiğim başlama anının gelip gelmediği"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-6-decision",scenario:"Leyla’nın çay molası sık sık iptal oluyor. Öğle yemeğinden dönme anı ise hâlâ var. Raporu masasında hazır tutabilir.",question:"Önce hangi değişikliği denemeye değer?",options:[{id:"identity-6-earlier-clock",text:"Çaydan sonra başlama planını korusun. Molaya zaman ayırabilmek için saatli hatırlatma kursun. Ardından rapora tek bir cümle yazsın.",feedback:"Hatırlatma fark etmeye yardımcı olabilir. Ama gerçekleşmeyen çay molasını ortaya çıkarmaz. Kayıt, sorunun o anın oluşmaması olduğunu gösteriyor. Başka bir hatırlatma eklemeden önce güvenilir dönüş anını dene."},{id:"identity-6-ready-tea-draft",text:"Çaydan sonra başlama planını korusun. Taslağı fincanının yanına koysun. Sonra çayını bitirdiğinde rapora tek bir cümle yazsın.",feedback:"Taslağa ulaşmak zorsa yerini değiştirmek yardımcı olur. Burada mola sürekli kayboluyor. Taslak zaten hazır bekleyebilir. Onu başka yere koymak, eksik başlama anını ortaya çıkarmıyor. Asıl aksayan koşul aynı kalıyor."},{id:"identity-6-reliable-event",text:"Öğle yemeğinden dönmeyi başlama anı seçsin. Taslağı hazır tutsun. O anda işe yarayan tek bir cümle yazmayı denesin.",feedback:"Bu seçim, planın hangi noktada aksadığını dikkate alıyor. Davranış aynı kalıyor, başlama anı zaten gerçekleşiyor. Malzeme hazır mıydı, cümle gerçekten yazıldı mı, kaydet. Yeni plan bunları kendiliğinden olmuş saymaz."}],bestOptionId:"identity-6-reliable-event"}},carry:{takeaway:"Kaydının gösterdiği koşulu düzelt. Daha fazla kural eklemeden önce bir kez dene.",followUp:{questionId:"identity-6-availability-return",question:"Yeni seçtiğin başlama anı gerçekten geldi mi?",observationPrompt:"Malzeme hazır mıydı? Ne işe yaradı, önüne ne çıktı?",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"Belirli bir plan, her zaman yapılabilir değildir",paragraphs:["Gollwitzer ve Sheeran’ın meta-analizi, belirli durum ve davranış planlarını ortalama olarak destekliyor [I01]. Tek bir ideal günlük düzeni değil, farklı hedefleri, örneklemleri ve yöntemleri kapsıyor. “Çaydan sonra yaz” belirli bir plan. Ama belirli olması, çayı senin haftanda güvenilir bir olay yapmaz. Planın mümkün olup olmadığına bakmak ve gerçekten bir kez denemek hâlâ gerekir.","ODA’nın yeni başlama anı denemesi, kendi kaydının gösterdiği koşulu değiştirir. Seçtiğin an hiç gelmediyse tanıyabileceğin başka bir olay dene. An geldiyse ama malzemeler eksikse onları hazır et. Yapacağın iş fazla geliyorsa miktarını değiştir. Ortada yokken isteksizlik sorunu uydurma. Her aksaklığa aynı yanıtı vermek yerine gerçekte kopan yeri ele al.","Bu, eğitim için bir uyarlamadır. Üç engel planının veya adı olan bir alışkanlık birleştirme yönteminin gerekli olduğuna dair kanıt değildir. İlk öneriler, düzenlenebilir örnek bir plan oluşturur. Ancak koşullarına uyanı seçip kaydettiğinde senin yapmaya karar verdiğin plan olur. Hazır öneri tek başına söz verdiğin anlamına gelmez."]},{heading:"Ortam uygulamayı destekler, her şeye karar vermez",paragraphs:["Wood ve Rünger, benzer ortamlarda tekrar eden davranışların gelişmesini anlatır [I06]. Alışkanlıklar ve bilinçli süreçler birlikte işleyebilir. Bu anlatı derlemesi, ortam değişikliklerinin her zaman çabadan üstün olduğu evrensel bir sıralama kurmaz. Her nesnenin sessizce sıradaki seçimini belirlediğini de kanıtlamaz. Çevreyi bir destek olarak görmek, bütün seçimlerini ona bağlamak değildir.","Bu denemede malzemenin yeri, kontrol edebileceğin somut bir koşul. Raporu çalışma masanın yakınında tut veya iletişim için kullandığın aracı konuşacağın yerde hazır tut. Bedelini de belirt: telefonu uzağa koymak kolayca erişmeni azaltabilir. Ama acil iletişim veya engellilik nedeniyle gereken destekler başka bir düzen gerektirebilir. Bu ihtiyaçları hazırlık uğruna ortadan kaldırma.","Tek bir koşulu değiştirmek, sonraki kaydını yorumlamayı kolaylaştırır. Yeni anın da uymadığını görmek işe yarayan bir sonuç olabilir. Hazırlığı tamamlanmış uygulama saymak yerine bu gerçeği koru. Yaptığın hazırlığı dürüstçe kaydedebilirsin. Asıl davranış için başka zaman seçebilir veya onu uyarlayabilirsin. Bir koşulun değişmesi, davranışın yapıldığı anlamına gelmez."]}],sourceIds:["identity-gollwitzer","identity-wood-runger"]}},{schemaVersion:2,revision:2,id:"identity-7",courseId:"identity",locale:"tr",title:"Birkaç gün yapamadın mı? Gücüne göre yeniden başla",goal:"Aynı denemeye dönüp bak. Gelecek hafta için yapabileceğin uygulama, destek veya toparlanma adımlarını seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Her gün yapamadın. Sıradaki planın hayatına mı yarıyor, yoksa sadece sayıyı mı düzeltiyor?",reason:{id:"identity-7-reason",label:"Bu denemeye haftanda hâlâ yer ayırmak istiyor musun?",kind:"text",maxLength:160,optional:!0,suggestions:["İşe yarayan kısmı aynı şekilde korumak","Yapacağım işi gücüme göre küçültmek","Telafi işi eklemeden dinlenip toparlanmak"]},why:{id:"identity-7-direction",label:"Bu hafta bu adım senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sık duyduğun 66 gün, bir davranışın ne kadar otomatikleştiğini tahmin ediyordu. İnsanların değişmeyi bitirdiği bir tarih değildi. Tahminler çok farklıydı. Bazıları araştırmanın gözlem süresinin ötesine uzanıyordu. Kendi davranışının ne zaman kolay gelmesi gerektiğini bu sayılardan çıkaramazsın. Onları kişisel bir bitiş tarihi olarak kullanma.","Aynı denemeye bak: yararlı davranışın, başlama anın, gerçek denemelerin ve ilgilenmen gereken koşul. Gücüne uyan bir fırsat seç. Tekrarla, küçült, yardım iste, dinlen veya artık sana katkısı olmayan hedefi bırak. Kursu bitirdiğini kanıtlamak için yeni bir ritüel ekleme. Yapamadığın günleri telafi etmek üzere kendine borç da yükleme."],example:{title:"Leyla daha küçük bir adımla dönecek",text:"Hastalık sonrası Leyla’nın rapor denemesinde üç gün uygulama yok. Yazdığı cümlelere ve işe yarayan öğle yemeği sonrası başlama anına bakıyor. Hâlâ bitkin. Bugün toparlanmayı, yarın durumuna tekrar bakmayı seçiyor. Tek bir cümlenin uygun olup olmadığına o zaman karar verecek. Boş günleri yeniden yazmak veya telafi seansı sözü vermek yerine verdiği arayı dürüstçe kaydediyor."}},move:{invitation:"Aynı denemeni gözden geçir. Sıradaki uygun fırsatı seç veya ara verip dönüş tarihini kaydet.",instructions:["Yararlı davranışı koru. Yalnızca kayıtlarının gerektirdiği değişikliği yap.","Gelecek hafta ne kadarını yapacağını ve başlama anını seç. Yapamadığın günler için telafi işi ekleme."],prompts:[],suggestions:{action:["İşe yarayan en küçük adımımı tekrar yap","Anlamlı, daha küçük bir kısmı dene","Bu denemem için somut destek iste"],minimum:["İşe yarayan tek bir cümle yaz","Yapabildiğim küçük bir uygulamayı tamamla","Somut bir ihtiyaç için destek iste"],cue:["Öğle yemeğinden döndüğüm bir sonraki uygun anda","Gücüm güvenli bir denemeye yettiğinde","Destek için seçtiğim görüşme başladığında"],place:["Genellikle kullandığım, erişebildiğim yerde","Güvenle destek isteyebildiğim bir konuşmada"],fallback:["Ara ver, yeniden bakmak için tarih seç","Asıl denemeyi daha küçük bir adımla yap","Önümdeki kısıt için somut yardım iste"],observation:["Davranışımın istediğim hayata katkısı","Şu anki gücüme neyin uyduğu","Yeniden başlamama hangi koşulun yardımcı olduğu"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan en küçük adımımı tekrar yap",minimum:"İşe yarayan tek bir cümle yaz",minutes:2,cueHint:"Öğle yemeğinden döndüğüm bir sonraki uygun anda",placeHint:"Genellikle kullandığım, erişebildiğim yerde",obstacleHint:"Denemediğim günleri telafi etmek istiyorum.",fallbackHint:"Ara ver, yeniden bakmak için tarih seç",observationHint:"Davranışımın istediğim hayata katkısı"},stopRule:"Bu durum tehlike veya kötü muamele içeriyorsa korunmayı ya da destek almayı seç.",accessibleAlternative:"Yaz, sesle yazdır, yardım al veya aynı amaca hizmet eden, erişebildiğin başka bir adım seç."},result:{question:"Seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Gerçekte ne yaptın, hemen ardından ne oldu?"},judgment:{primary:{id:"identity-7-decision",scenario:"Leyla hastayken uygulama yapmadı. Hâlâ bitkin. Kaydı, öğle yemeği sonrası başlama anının daha önce işe yaradığını gösteriyor.",question:"Hangi yeni plan gördüklerine ve bugünkü gücüne uyar?",options:[{id:"identity-7-preserve-volume",text:"Düzeni bozmamak için bugün aynı başlama anını kullansın. Her zamanki miktarda yazıyı daha yavaş yazarak tamamlasın.",feedback:"Gücü geri geldiğinde tanıdık bir an yardımcı olabilir. Ama bitkinliği geçersiz kılmaz. Kayıt, başlama anını destekliyor. Bugün her zamanki miktarı yazmasını değil. Toparlanmak ve tarih seçip yeniden değerlendirmek uygun olabilir."},{id:"identity-7-reassess-capacity",text:"Bugün dinlensin. Gücüne yeniden bakacağı bir tarih seçsin. Uygun olduğunda daha küçük, yararlı bir adımla geri dönsün.",feedback:"Bu seçim toparlanmayı başarısızlık saymadan yararlı denemeyi koruyor. Yazmış gibi davranmak yerine, yeniden karar vereceği bir tarih seçiyor. Sıradaki deneme, Leyla’nın o anda gerçekten sahip olduğu güce uymalı. Eski plan bu kararı onun yerine vermez."},{id:"identity-7-catch-up",text:"Bu haftaki ilk toplam hedefi yine tutturmak için yapamadığı işleri hafta sonundaki daha uzun bir çalışma zamanına taşısın.",feedback:"Gerçek bir ihtiyaç için daha sonraki çalışma seçilebilir. Ama kaçırılan uygulama bilimsel bir telafi zorunluluğu yaratmaz. Daha büyük iş toparlanmaya uymayabilir. Sıradaki adımı büyütmeden önce o andaki gücünü yeniden değerlendir."}],bestOptionId:"identity-7-reassess-capacity"}},carry:{takeaway:"Yararlı denemeni koru, koşullarına uymayan kısmını değiştir. Bambaşka biri olmak için kendine son tarih koymadan geri dön.",followUp:{questionId:"identity-7-return",question:"Seçtiğin dönüş, gücüne ve istediğin yola uydu mu? Sıradaki plan değişmeli mi?",observationPrompt:"Gücüne ve istediğin yola ne uydu? Neyi değiştirmek gerekiyor?",adjustmentPrompt:"Bir dahaki denemede neyi korumak, değiştirmek veya bırakmak istersin?"}},goDeeper:{sections:[{heading:"O ünlü sayı, otomatikleşmenin model tahminiydi",paragraphs:["Lally ve arkadaşları yeme, içme veya fiziksel etkinlik davranışı seçen 96 gönüllüyü 84 gün izledi [I04]. 82 kişi yeterli veri verdi. 62 model kuruldu, 39’u verilere iyi uydu. Bu modellerde, otomatikleşmenin ulaşacağı sabit düzeyin %95’ine ulaşma süresinin ortancası 66 gündü. Aralık 18-254 gündü. Bu sayılar modelin verdiği tahminlerdi.","Daha uzun süreler gözlemin ötesine uzanan tahminlerdi. Araştırma herkesin “alışkanlığı bitirmesini” izlemedi, yeni kişilik ölçmedi veya üst üste iki gün kaçırma kuralını sınamadı. Analizde tek kaçırılan fırsat, oluşumu belirgin biçimde değiştirmedi. Bu sonuç daha uzun aralar için evrensel bir yeniden başlama kuralı kuramaz. Tek fırsatla uzun arayı aynı bulgu sayamayız.","Daha sonraki 20 sağlık davranışı çalışmasını kapsayan derleme de büyük farklılıklar buldu [I05]. Yalnızca dört çalışma oluşma sürelerini bildirdi. On bir çalışmada yanlılık riski yüksekti. İki kaynak da yazmanın, dinlemenin veya ODA’da seçtiğin başka bir davranışın ne zaman otomatikleşmesi gerektiğini söylemez."]},{heading:"Yeni ritüel eklemek yerine elindeki kayıtları toparla",paragraphs:["Harkin ve arkadaşları, ilerleme takibini artıran uygulamaları 138 rastgele kontrollü çalışmada inceledi [I02]. Hedefe ulaşma ortalama olarak arttı. Yanlılığa göre düzeltilmiş tahmin daha küçüktü. Yöntemler ve hedefler farklıydı. Derleme, on beş dakikalık haftalık değerlendirmenin, kesintisiz gün sayısının veya gelecekteki kendine mektup yazmanın en iyi biçim olduğunu göstermiyor. Buradan tek bir zorunlu düzen çıkmaz.","Bu kursun sonunda kayıtları topluca değerlendirmek, ODA’nın tasarım seçimi. Aynı denemenin kayıtlarını oku. Gerçek denemeleri planlardan ve aralardan ayır. Korumaya değer koşulu belirle. Gelecek için plan yapmak, davranışı tamamlamış olmak değildir. Ne olduğunu söyleyene kadar eksik kayıtlar bilinmeyen olarak kalır. Onları kendiliğinden başarı veya başarısızlık sayma.","Gelecek hafta ne kadarını yapacağını ve hangi olayda başlayacağını ancak deneme hâlâ istediğin hayata katkı sağlıyorsa seç. Destek, toparlanma, sınır koyma veya durma bilinçli yanıtlar olabilir. Adlarını doğru koy. Düşünerek geri dönmek için yeni bir kimlik cümlesi, daha uzun çalışma veya yapamadığın günlerin telafisi gerekmiyor. Yeni planın bugünkü koşullarına uyabilir."]}],sourceIds:["identity-lally","identity-habit-times","identity-harkin"]}}],m=[{id:"identity-1",schemaVersion:2,practice:["Alışık olduğun tek bir an seç. İstediğin yola somut katkısı olacak başka bir davranış dene.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:1,photo:{id:"1519087630026-63fb0dab69bb",alt:"Duvardaki aynada kendi yansımasına bakan kadın"}},{id:"identity-2",schemaVersion:2,practice:["Aynı denemeyi sürdür. İşine yarayacaksa gündelik duygunu adlandır. Sonra seçtiğin davranışı yap.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:2,photo:{id:"1762126242240-cafa01fb1351",alt:"Koltuğa oturup yağmurlu bir pencereden dışarı bakan kişi"}},{id:"identity-3",schemaVersion:2,practice:["Aynı davranışı koru. Durumu geç fark ettiğinde ardından ne yapacağını seç.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:0,photo:{id:"1626257690705-8d62125575b0",alt:"Gündüz şehirdeki yaya yolunda koyu renk ceketle yürüyen adam"}},{id:"identity-4",schemaVersion:2,practice:["Kaydettiğin en küçük adıma bak. Sadece hazırlıksa adını dürüstçe koy veya asıl davranışı denemeyi seç.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:1,photo:{id:"1787154604447-4a62ed6654e3",alt:"Koyu renk başörtüsü ve spor kıyafetleriyle şehirde bir sokakta koşan kadın"}},{id:"identity-5",schemaVersion:2,practice:["Hazırlık yardımcı olacaksa kısa tut. Denemenin kaydına, gerçekte yaptığın işi yaz.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:0,photo:{id:"1600618528240-fb9fc964b853",alt:"Gün batımında ahşap terasta meditasyon yapan kadın"}},{id:"identity-6",schemaVersion:2,practice:["Tek bir kayda bakarak aksayan bir koşulu değiştir. Mevcut davranışını yeni başlama anında dene.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:2,photo:{id:"1675762647949-1b25f669a687",alt:"Ahşap zemin üzerinde duran bir çift beyaz ayakkabı"}},{id:"identity-7",schemaVersion:2,practice:["Aynı denemeni gözden geçir. Sıradaki uygun fırsatı seç veya ara verip dönüş tarihini kaydet.","Seçtiğin an geldiğinde kayıtlı en küçük adımını dene veya ara verdiğini kaydet.","Gerçekte ne olduğunu buraya kaydet. Tarihli değerlendirmende sıradaki denemeyi seç."],correct:1,photo:{id:"1760715160644-7f5939675b68",alt:"Altın rengi çayırlıktaki patikada yürüyen doğa yürüyüşçüleri"}}],y={id:"identity",title:"Yine eski alışkanlığın mı? Bu hafta bir davranışını değiştir",subtitle:"Yedi derste seni aynı davranışa götüren anı bul. İşe yarayan başka bir adım dene, yaptıklarına bakarak onu geliştir.",description:"İstediğin bir şeye yer bırakmayan tek bir davranış seç. Senin için anlamlı başka bir adım dene. Gerçekte ne olduğunu kaydet. Başlama anını, hazırlığı veya aldığın desteği hayatına daha iyi uyacak şekilde değiştir.",outcome:"Anlamlı bir adım, denenmiş bir başlama anı ve haftana uyan dürüst bir yeniden başlama planı.",scope:"Alışık olduğun düşünme, hissetme veya tepki verme biçimini gündelik hayatta değiştirmek isteyen bir yetişkinsen bu kurs sana yol gösterir. Dr. Joe Dispenza ve James Clear’ın fikirlerinden yararlanır. Araştırmanın hangi fikirleri desteklediğini, hangilerini desteklemediğini açıkça belirtir. Terapi değildir. Depresyon, kaygı, travma veya herhangi bir hastalığın tedavisi değildir. Zorlanıyorsan bir sağlık uzmanıyla konuş. Kriz durumunda bulunduğun yerdeki acil yardım numarasını ara.",photo:{id:"1611569518992-0927098278b7",alt:"Yeşil ağaçların arasındaki toprak yolda tek başına yürüyen kadın"},lang:"tr",lessons:t.map((a,d)=>{const r=m[d],e=a.judgment.primary,n=e.options.find(i=>i.id===e.bestOptionId),l=e.options.filter(i=>i.id!==n.id).map(i=>i.text);return l.splice(r.correct,0,n.text),{...r,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:l,feedback:n.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}})};export{y as COURSE,t as LESSONS_V2,k as SOURCES};
